int good(int ar[][100],int r,int c)
{
    int i=0,j=0,goodness=0,pos1=-1,pos2=-1,ans=0;
    for(;i<r;i++)
    {
        for(j=0;j<c;j++)
        {
            if(ar[i][j]!=0)
            {
                goodness=check(ar,r,c,i,j);
                if(goodness>ans)
                {
                    pos1=i;
                    pos2=j;
                    ans=goodness;
                }
            }
        }
    }
    if(ans==0)
        printf("%d %d %d",0,-1,-1);
    else
        printf("%d %d %d",ans,pos1+1,pos2+1);
    return ans;
}

int check(int ar[][100],int r,int c,int pos1,int pos2)
{
    int i=0,j=0,size=0;
    for(i=0;(i+pos1<r)&&(i+pos2<c);i++)
    {
        if(ar[i+pos1][i+pos2]==0)
            break;
    }
    if(i==1)
        return 0;
    size=i;
    for(i=0;i<size;i++)
    {
        for(j=0;j<size;j++)
        {
            if(i!=j)
            {
                if(ar[i+pos1][j+pos2]!=0)
                {
                    size=max(i,j);
                }
            }
        }
    }
    if(size==1&&size==0)
        return 0;
    else return size;
}

#include <stdio.h>
void read_into_matrix(int a[][10],int m,int n){
    for(int i=0;i<=m-1;i++){
        for(int j=0;j<=n-1;j++){
            scanf("%d",&a[i][j]);
        }
    }
}
int goodness(int a[][10],int i,int j,int n){
    int k,l=0;
    for(k=0;k<=n-1;k++){
        if(a[i+k][j+k]!=0){
        l++;
        }
    }
    for(int p=0;p<=n-1;p++){
        for(int q=0;q<=n-1;q++){
            if(p!=q&&a[i+p][j+q]==0){
            l++;
            }
        }

    }
    if(l==n*n)
        return 1;
        else
        return 0;
}
int min(int a,int b){
    if(a<b)
    return a;
    else 
    return b;
}
int max(int a,int b){
    return a+b-min(a,b);
}
int max_matrix(int a[][10],int m,int n){
    int maximum=a[0][0];
    for(int i=0;i<=m-1;i++){
        for(int j=0;j<=n-1;j++){
            maximum=max(maximum,a[i][j]);
        }
    }
    return maximum;
}
